      float t = (float(j) + jit) / float(steps);
      vec2 uv = vUV + dir * rs * t * t;                                    // denser close to the pixel
      if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) break;
