        float t = (float(i) + j) / 8.0 * uA.y;
        vec3 s = ToScreen(P0 + uSunD.xyz * t);
        if (s.x < 0.0 || s.y < 0.0 || s.x > 1.0 || s.y > 1.0) break;
        float sd = LinDepth(texture(uDepth, s.xy).r), rd = LinDepth(s.z);
        float dz = rd - sd;
