  float phase = (1.0 - g * g) / (12.566 * pow(1.0 + g * g - 2.0 * g * mu, 1.5)) * 6.0 + 0.25;   // Henyey-Greenstein, forward scattering
  float muM = dot(dir, uMoonV.xyz);
  float phaseM = (1.0 - g * g) / (12.566 * pow(1.0 + g * g - 2.0 * g * muM, 1.5)) * 6.0 + 0.25;
